        if (onun > enIyiR) enIyiR = onun;
        if (avAktif) {
          for (z = 0; z < N; z++) {
            if (onIki[z] && db[z] >= 0) {
              if (db[z] === 1) cokYakin = 1;
              else if (db[z] >= 2 && db[z] < avMes) avMes = db[z];
            }
          }
        }
